<?php
namespace App\Services;
use App\Models\BusinessProfile;use App\Models\Order;use App\Models\OrderDocument;use Dompdf\Dompdf;use Illuminate\Support\Facades\Storage;
class ReceiptService{
 public function generate(Order$order,string$type,$user):OrderDocument{$order->load(['items.flavors','items.modifiers','payments','delivery','customer']);$profile=BusinessProfile::firstOrCreate(['branch_id'=>$order->branch_id],['name'=>'Pizzería POS']);$html=$this->html($order,$profile);$dir='receipts/'.$order->order_date->format('Y-m-d');$base=$dir.'/order-'.$order->id.'-'.now()->format('His');if($type==='customer_html'){$path=$base.'.html';Storage::put($path,$html);}elseif($type==='customer_pdf'){$pdf=new Dompdf;$pdf->loadHtml($html);$pdf->setPaper([0,0,226.77,700]);$pdf->render();$path=$base.'.pdf';Storage::put($path,$pdf->output());}elseif($type==='customer_image'){$path=$base.'.svg';Storage::put($path,$this->svg($order,$profile));}else{$path=null;}return OrderDocument::create(['order_id'=>$order->id,'user_id'=>$user->id,'type'=>$type,'path'=>$path,'content'=>$path?null:$html]);}
 public function html(Order$o,BusinessProfile$p):string{$items=$o->items->map(fn($i)=>'<tr><td>'.e($i->quantity).' × '.e($i->name).'</td><td>$'.number_format((float)$i->total,2).'</td></tr>')->join('');$payments=$o->payments->map(fn($x)=>'<div>'.e($x->method).': $'.number_format((float)$x->amount,2).'</div>')->join('');return'<!doctype html><html><head><meta charset="utf-8"><style>body{font:14px Arial;color:#29231f;padding:18px}h1{color:'.e($p->primary_color).';margin:0}table{width:100%;margin:18px 0}td:last-child{text-align:right}.total{font-size:20px;font-weight:bold;border-top:2px solid;padding-top:10px}.muted{color:#777} @media print{button{display:none}}</style></head><body><h1>'.e($p->name).'</h1><div>'.e($p->address).'</div><h2>Orden #'.$o->daily_number.'</h2><div class="muted">'.$o->created_at->format('d/m/Y H:i').'</div><table>'.$items.'</table><div class="total">Total: $'.number_format((float)$o->total,2).'</div>'.$payments.'<p>'.e($p->receipt_footer).'</p><button onclick="print()">Imprimir</button></body></html>';}
 private function svg(Order$o,BusinessProfile$p):string{$lines=[];$y=130;foreach($o->items as$i){$lines[]='<text x="30" y="'.$y.'">'.e($i->quantity.' × '.$i->name).'</text>';$lines[]='<text x="570" y="'.$y.'" text-anchor="end">$'.number_format((float)$i->total,2).'</text>';$y+=34;}$height=max(400,$y+130);return'<svg xmlns="http://www.w3.org/2000/svg" width="600" height="'.$height.'"><rect width="100%" height="100%" fill="#fffdf9"/><style>text{font:22px Arial;fill:#29231f}.h{font:bold 34px Arial;fill:'.e($p->primary_color).'}.t{font:bold 28px Arial}</style><text class="h" x="30" y="50">'.e($p->name).'</text><text class="t" x="30" y="95">Orden #'.$o->daily_number.'</text>'.join('',$lines).'<line x1="30" x2="570" y1="'.($y+10).'" y2="'.($y+10).'" stroke="#29231f"/><text class="t" x="570" y="'.($y+55).'" text-anchor="end">Total $'.number_format((float)$o->total,2).'</text></svg>';}
}
